// Flatten every page into one contact list, hash each address, and CAPTURE
// THE CONTACT'S STATUS.
//
// Why status matters: check_suppression is status-aware. It suppresses an
// address when the status is in config.never_mail_statuses, or when
// last_job_at falls inside the lapse window. A row with NEITHER reads as a
// lead and is NOT suppressed. The previous version of this workflow wrote no
// status at all, so a completed backfill produced a full cache that
// suppressed nobody - while satisfying the can_send row check and opening
// the gate. Verified against the live function before this rewrite.
//
// The hashing rules below MUST stay identical to src/lib/address.js and
// _shared/address.ts, or suppression silently breaks.

const crypto = require('crypto');

const DIRECTIONALS = {north:'n',south:'s',east:'e',west:'w',northeast:'ne',northwest:'nw',southeast:'se',southwest:'sw',n:'n',s:'s',e:'e',w:'w',ne:'ne',nw:'nw',se:'se',sw:'sw'};
const STREET = {street:'st',st:'st',avenue:'ave',ave:'ave',av:'ave',road:'rd',rd:'rd',drive:'dr',dr:'dr',lane:'ln',ln:'ln',court:'ct',ct:'ct',circle:'cir',cir:'cir',boulevard:'blvd',blvd:'blvd',boul:'blvd',place:'pl',pl:'pl',terrace:'ter',ter:'ter',terr:'ter',parkway:'pkwy',pkwy:'pkwy',pky:'pkwy',highway:'hwy',hwy:'hwy',trail:'trl',trl:'trl',way:'way',square:'sq',sq:'sq',loop:'loop',crescent:'cres',cres:'cres',close:'cl',gardens:'gdns',gdns:'gdns',heights:'hts',hts:'hts',junction:'jct',jct:'jct',manor:'mnr',mnr:'mnr',point:'pt',pt:'pt',ridge:'rdg',rdg:'rdg',station:'sta',sta:'sta',extension:'ext',ext:'ext'};
const UNIT = new Set(['apt','apartment','unit','ste','suite','rm','room','fl','floor','bldg','building','dept','department','lot','trlr','trailer','spc','space','key','slip','hangar','pier','basement','bsmt','front','frnt','lower','lowr','upper','uppr','rear','side','penthouse','ph']);
const ORD = {first:'1st',second:'2nd',third:'3rd',fourth:'4th',fifth:'5th',sixth:'6th',seventh:'7th',eighth:'8th',ninth:'9th',tenth:'10th',eleventh:'11th',twelfth:'12th'};

function stripDia(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');}

function normaliseAddress(address){
  if(address==null) return '';
  let s=stripDia(String(address)).toLowerCase();
  s=s.replace(/[,]/g,' ').replace(/#\s*/g,' apt ').replace(/[.'\u2019]/g,'').replace(/[^a-z0-9]+/g,' ');
  let toks=s.split(' ').filter(Boolean);
  if(!toks.length) return '';
  const out=[];
  for(let i=0;i<toks.length;i++){
    if(UNIT.has(toks[i])){ const nx=toks[i+1]; if(nx!==undefined && /^[a-z0-9]{1,6}$/.test(nx)) i++; continue; }
    out.push(toks[i]);
  }
  if(out.length) toks=out;
  toks=toks.map(t=>ORD[t]||t).map(t=>DIRECTIONALS[t]||STREET[t]||t);
  return toks.join(' ');
}

function normalisePostal(pc){
  if(pc==null) return '';
  let s=stripDia(String(pc)).toLowerCase().replace(/[^a-z0-9]+/g,'');
  if(/^\d{9}$/.test(s)) return s.slice(0,5);
  return s;
}

function addressHash(address,postal){
  const a=normaliseAddress(address);
  if(a==='') return null;
  const p=normalisePostal(postal);
  return crypto.createHash('sha1').update(a+'|'+p).digest('hex').slice(0,12);
}

// HighLevel does not expose one canonical "status" on a contact, and it
// differs by how the sub-account is set up. Read the plausible fields in
// priority order and report what was actually found, rather than assuming.
function readStatus(c){
  const direct = c.status ?? c.contactStatus ?? c.type ?? c.contactType;
  if (direct != null && String(direct).trim() !== '') return String(direct).trim();
  // Some accounts keep it on a custom field instead.
  const cf = c.customFields || c.custom_fields || [];
  if (Array.isArray(cf)) {
    for (const f of cf) {
      const key = String(f.key || f.name || f.id || '').toLowerCase();
      if (key.includes('status')) {
        const v = f.value ?? f.fieldValue;
        if (v != null && String(v).trim() !== '') return String(v).trim();
      }
    }
  }
  return null;
}

// Values go into SQL literals below, so every one is validated to a strict
// charset first. Nothing that fails validation reaches the statement.
function sqlText(v){
  if (v == null || v === '') return 'null';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function safeId(v){
  const s = String(v == null ? '' : v).trim();
  return /^[A-Za-z0-9_\-:.]{1,128}$/.test(s) ? s : null;
}
function safeStatus(v){
  if (v == null) return null;
  const s = String(v).replace(/[^A-Za-z0-9 _\-\/]/g, '').trim().slice(0, 64);
  return s === '' ? null : s;
}

let contacts=[];
for(const item of $input.all()){
  const c=item.json.contacts || (item.json.contact ? [item.json.contact] : []);
  if(Array.isArray(c)) contacts=contacts.concat(c);
}

const locationId = safeId($('When Called').first().json.locationId);
if (!locationId) throw new Error('locationId is missing or not a safe identifier');

const dryRun = String($('When Called').first().json.dryRun ?? '').toLowerCase() === 'true';

const statusCounts = {};
const byHash = new Map();
let skippedNoAddress = 0, rippleSourced = 0, noStatus = 0;

for(const c of contacts){
  const addr = c.address1||c.address||c.line1||'';
  const postal = c.postalCode||c.postal_code||c.zip||'';
  const h = addressHash(addr, postal);
  if(h===null){ skippedNoAddress++; continue; }

  const tags = Array.isArray(c.tags) ? c.tags.map(t=>String(t).toLowerCase()) : [];
  const src = String(c.source || '').toLowerCase();
  const isRipple = tags.includes('ripple_neighbor') || src.includes('ripple');
  if (isRipple) rippleSourced++;

  const raw = readStatus(c);
  const status = safeStatus(raw);
  const key = raw == null ? '(none)' : String(raw);
  statusCounts[key] = (statusCounts[key] || 0) + 1;
  if (status === null) noStatus++;

  // Several contacts can share one address. Keep the one that carries a
  // status - losing it to a blank duplicate would un-suppress the household.
  const prev = byHash.get(h);
  if (!prev || (prev.status === null && status !== null)) {
    byHash.set(h, { addr_hash: h, ghl_contact_id: safeId(c.id||c._id), status: status });
  }
}

const rows = Array.from(byHash.values());

// One statement per chunk instead of one per contact: the Postgres node's
// queryReplacement splits on commas, so any value containing one corrupts the
// parameter list (the documented WF0 bug). Building validated literals avoids
// parameters entirely, and turns thousands of round trips into a handful.
const CHUNK = 500;
const chunks = [];
for (let i = 0; i < rows.length; i += CHUNK) {
  const slice = rows.slice(i, i + CHUNK);
  const values = slice.map(r =>
    '(' + sqlText(locationId) + ',' + sqlText(r.addr_hash) + ',' +
    sqlText(r.ghl_contact_id) + ",'sync'," + sqlText(r.status) + ',' +
    (r.status === null ? 'null' : 'now()') + ',now())'
  ).join(',\n');

  chunks.push({ json: {
    _chunk: true,
    index: chunks.length,
    rows: slice.length,
    sql:
      'insert into client_addresses (location_id, addr_hash, ghl_contact_id, source, status, status_synced_at, last_seen_at) values\n' +
      values +
      '\non conflict (location_id, addr_hash) do update set\n' +
      '  ghl_contact_id = coalesce(excluded.ghl_contact_id, client_addresses.ghl_contact_id),\n' +
      // A blank status must never overwrite a known one: that would silently
      // un-suppress a customer.
      '  status = coalesce(excluded.status, client_addresses.status),\n' +
      '  status_synced_at = coalesce(excluded.status_synced_at, client_addresses.status_synced_at),\n' +
      '  last_seen_at = now();'
  }});
}

const summary = {
  _summary: true,
  location_id: locationId,
  dry_run: dryRun,
  total_contacts: contacts.length,
  unique_addresses: rows.length,
  skipped_no_address: skippedNoAddress,
  ripple_sourced_contacts: rippleSourced,
  addresses_without_status: noStatus,
  status_values_found: statusCounts,
  chunks: chunks.length
};

if (dryRun) return [{ json: summary }];
return [{ json: summary }, ...chunks];

// Collapse every chunk result into ONE item, so the gate is flipped once
// rather than once per chunk.
const s = $('Hash + Read Status').first().json;
return [{ json: { location_id: s.location_id, chunks_written: $input.all().length } }];

// Readable run summary. status_values_found is the important one: it lists
// exactly what HighLevel returned, so config.never_mail_statuses can be set
// to match reality instead of a guess.
const s = $('Hash + Read Status').first().json;
const g = $input.first().json || {};
return [{ json: {
  done: true,
  location_id: s.location_id,
  total_contacts: s.total_contacts,
  unique_addresses: s.unique_addresses,
  skipped_no_address: s.skipped_no_address,
  addresses_without_status: s.addresses_without_status,
  ripple_sourced_contacts: s.ripple_sourced_contacts,
  status_values_found: s.status_values_found,
  cached_addresses: g.cached_addresses ?? null,
  with_status: g.with_status ?? null,
  gate_opened: !!g.address_backfill_completed_at
} }];

// Dry run: report what WOULD be written, touch nothing. Run this first on any
// new client and read status_values_found before letting it write.
const s = $input.first().json;
return [{ json: Object.assign({ done: true, wrote_nothing: true }, s) }];

// Reached only when the token isn't active. Fail loudly rather than
// silently completing a backfill for a revoked client.
return [{ json: { done: false, reason: 'token_not_active', locationId: $('When Called').first().json.locationId } }];
